head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[selectbox > M > deleteItem]<br/>컴포넌트에서 특정 아이템을 제거합니다.",
    "validation" : [                        
        "visibleColumn 속성으로 숨겨진 아이템도 제거할 수 있습니다.",
    ]
} 



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }    

    let properties = {
        visibleColumn : "visible_col",
    }

    let cList = $c.gcm.createCList(properties)
    let eList = $c.gcm.createEList(["onchange"]);

    // target 생성    
    let grp_comp = document.querySelector('.tc_group_basic');
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="index=0~3 은 visibleColumn 에 의해 미표시 상태임"', '', 'label1')

    strTarget += '<xf:select1 ' + strNameSpace + ' ' + cList + ' ' + eList + ' style="width:200px; height:30px;">';
    strTarget += '<xf:choices>';
    strTarget += '<xf:itemset nodeset="data:dlt_selectboxItem">';
    strTarget += '<xf:label ref="label_col"></xf:label>';
    strTarget += '<xf:value ref="value_col"></xf:value>';
    strTarget += '</xf:itemset>';
    strTarget += '</xf:choices>';
    strTarget += '</xf:select1>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "selectbox",
        strTarget,
        grp_comp
    ); 
}



scwin.btn_deleteItem_onclick = function (e) {
    let index = par_index.getValue();
    let refresh = par_refresh.getText();
    let rtn = '';

    if (refresh == '')
	    rtn = target1.deleteItem(index);
    else
        if (refresh == "true")
            rtn = target1.deleteItem(index, true);
        else
            rtn = target1.deleteItem(index, false);

    wf_body_bottom.getObj("scwin").setReturnValue("object : " + rtn);
    wf_body_bottom.getObj("scwin").setReturnValue("object.label : " + rtn.label);
    wf_body_bottom.getObj("scwin").setReturnValue("object.value : " + rtn.value);
    wf_body_bottom.getObj("scwin").setReturnValue("object.orgLabel : " + rtn.orgLabel);
};



scwin.target1_onchange = function (info) {
    wf_body_bottom.getObj("scwin").setReturnValue("value : " + info.newValue);
    wf_body_bottom.getObj("scwin").setReturnValue("label : " + target1.getText());
    wf_body_bottom.getObj("scwin").setReturnValue("index : " + target1.getSelectedIndex());
}



scwin.btn_getDataList_onclick = function (e) {
	// let rsData  = dlt_ref.getAllJSON();
    let rsData = gdl_selectbox.getAllJSON();

    for(var i = 0; i < rsData.length; i++) {        
        wf_body_bottom.getObj("scwin").setReturnValue("label 값 : " + rsData[i].label);
    }
};



scwin.btn_getText_onclick = function (e) {
    let rtn = '';
    rtn = target1.render.textContent;

    wf_body_bottom.getObj("scwin").setReturnValue("selectbox 의 label : " + rtn);    


    let comp = "target1_itemTable_main";
    let targetElements = document.querySelectorAll('[id*='+comp+']');

    if (targetElements.length == 0)
        wf_body_bottom.getObj("scwin").setReturnValue("SelectBox 의 아이템 리스트를 한번 오픈해야 아이템 리스트 정보를 가져올 수 있음");

    let tds = targetElements[0].querySelectorAll('td.w2table_sb_col');

    // 각 td 요소의 visible 확인
    tds.forEach((td, index) => {   
        let itemLabel = td.textContent;
        wf_body_bottom.getObj("scwin").setReturnValue("item index=" + index + " 의 label : " + itemLabel);	
    });	
};
